namespace Challenge;public record Order(string Id,string Owner,string Status,string Note);public sealed class Orders(Dictionary<string,Order> data){public Order? Get(string actor,string id)=>data.GetValueOrDefault(id);public string Update(string actor,string id,string note){if(!data.TryGetValue(id,out var o))return "NotFound";data[id]=o with{Note=note};return "Ok";}public string Cancel(string actor,string id){if(!data.TryGetValue(id,out var o))return "NotFound";data[id]=o with{Status="Cancelled"};return "Ok";}}
